      if (times.length >= ADD_LIMIT) return fail('TooMany', {})
      times.push(now)
      const item = { id: notes.nextId(), title: clean, pinned: false, createdAt: new Date().toISOString(), archived: false, sharedWith: [], number: nextNumber(notes, keyOf(session)) }
